import{_ as o,o as t,c,ag as i}from"./chunks/framework.D5hoimZQ.js";const _=JSON.parse('{"title":"科学日报 · 2026-09-22（神经科学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-09-22.md","filePath":"topics/neuroscience/science-daily-2026-09-22.md"}'),n={name:"topics/neuroscience/science-daily-2026-09-22.md"};function a(r,e,s,l,d,u){return t(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="科学日报-·-2026-09-22-神经科学" tabindex="-1">科学日报 · 2026-09-22（神经科学） <a class="header-anchor" href="#科学日报-·-2026-09-22-神经科学" aria-label="Permalink to &quot;科学日报 · 2026-09-22（神经科学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> — 第29期</p></blockquote><hr><h2 id="异源皮层-xenocortication-给人源类器官腾出整块皮层-换来回路与行为层面的读出-nature" tabindex="-1">异源皮层（xenocortication）：给人源类器官腾出整块皮层，换来回路与行为层面的读出（Nature） <a class="header-anchor" href="#异源皮层-xenocortication-给人源类器官腾出整块皮层-换来回路与行为层面的读出-nature" aria-label="Permalink to &quot;异源皮层（xenocortication）：给人源类器官腾出整块皮层，换来回路与行为层面的读出（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-22.md</code> ｜ DOI: 10.1038/s41586-026-11032-2</p></blockquote><ul><li>痛点：人脑组织难获取；把神经类器官移植进啮齿动物体内是替代路线，但<strong>空间限制 + 与宿主回路竞争</strong>抑制了整合——而整合恰恰是研究疾病的关键。</li><li>做法：用遗传策略清除小鼠新皮层与海马的谷氨酸能神经元（<strong>apallial</strong>，即&quot;无皮层&quot;），在新生期把人源皮层类器官（hCO）植入皮层腔，得到 xenocortical 小鼠。</li><li>结果：hCO <strong>占据大部分皮层体积</strong>，生成多种人皮层细胞类型（含第 5 层端脑外投射神经元）；人神经元与小鼠神经系统整合，活体<strong>全移植块钙成像</strong>与电生理显示类似发育中回路的有序活动。</li><li>行为：运动大体保留，但<strong>肢体协调出现选择性差异</strong>、自发行为组织发生改变；平台还能在&quot;发育中人皮层细胞损伤&quot;模型上做行为读出。</li><li>洞察：这是&quot;<strong>先拆除、再植入</strong>&quot;策略在神经发育模型里的兑现——移植失败的瓶颈往往不是细胞质量，而是宿主的结构占位。可与本主题&quot;具身认知&quot;主线对照：行为变化只在<strong>协调与自发组织</strong>上显现，而不是运动能力本身，说明回路层测的是动态编排而非单个功能模块。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/neuroscience/index.md</code> ｜ 第29期 科学板块</p></blockquote><p>关键词：类器官、xenocortication、异源皮层、apallial、人源神经元、皮层整合、钙成像、神经发育、疾病建模 关联：<code>topics/neuroscience/index.md</code>（具身认知：行为是全身/全回路的事）、<code>topics/biomedicine/2026-q3-breakthroughs.md</code>（干细胞与再生模型）、<code>topics/neuroscience/science-daily-2026-09-14.md</code>（睡眠与皮层抑制）</p>',9)])])}const q=o(n,[["render",a]]);export{_ as __pageData,q as default};
